import sys
lines = sys.stdin.read().splitlines()
out = []
trie = {}
def add(w):
    node = trie
    for c in w: node = node.setdefault(c, {})
    node['#'] = True
def search(node, w, idx):
    if idx == len(w): return '#' in node
    ch = w[idx]
    if ch == '.':
        return any(search(node[nxt], w, idx + 1) for nxt in node if nxt != '#')
    if ch not in node: return False
    return search(node[ch], w, idx + 1)
if lines:
    m = int(lines[0])
    for line in lines[1:1+m]:
        cmd = line.split()
        if not cmd: continue
        if cmd[0] == 'ADD': add(cmd[1])
        elif cmd[0] == 'SEARCH': out.append('true' if search(trie, cmd[1], 0) else 'false')
print(' '.join(out))
